from playwright.async_api import (
    Page,
    TimeoutError as PlaywrightTimeoutError,
    expect,
)


class DashboardPage:
    CATEGORIES = ["Privileged", "Casual", "Encashed", "Taken"]

    SIDE_NAVIGATION = [
        "Collapse",
        "Dashboard",
        "Leave & Absence Tracker",
        "Holiday Calendar",
    ]

    def __init__(self, page: Page):
        self.page = page

    # filename: pages/dashboard_page.py | Code Generated by Sidekick is for learning and experimentation purposes only.

