    async def _open_profile_menu(self):
        await self.dismiss_cookie_dialog()

        profile_name = self.page.locator(
            "span.user-profile-trigger-name"
        ).first

        await expect(profile_name).to_be_visible(
            timeout=30_000
        )

        await profile_name.scroll_into_view_if_needed()

        profile_trigger = profile_name.locator("xpath=..")

        await profile_trigger.click(
            force=True,
            timeout=10_000,
        )

        await self.page.wait_for_timeout(500)



