    async def validate_side_navigation(self):
        await self.dismiss_cookie_dialog()

        # Close the profile dropdown if it is still open.
        await self.page.keyboard.press("Escape")
        await self.page.wait_for_timeout(300)

        async def is_visible_text(text):
            locator = self.page.get_by_text(text, exact=True)

            for index in range(await locator.count()):
                if await locator.nth(index).is_visible():
                    return True

            return False

        # Expand the sidebar only when "Collapse" is not currently visible.
        if not await is_visible_text("Collapse"):
            menu_icon = self.page.locator(
                "img[alt='collapse menu icon']"
            )

            if not await menu_icon.count():
                menu_icon = self.page.get_by_role(
                    "img",
                    name=re.compile(
                        r"collapse menu icon",
                        re.IGNORECASE,
                    ),
                )

            if not await menu_icon.count():
                raise AssertionError(
                    "The sidebar menu icon was not found."
                )

            menu_icon = menu_icon.first

            await menu_icon.click(
                force=True,
                timeout=10_000,
            )

            for _ in range(20):
                if await is_visible_text("Collapse"):
                    break

                await self.page.wait_for_timeout(250)

        expected_options = [
            "Collapse",
            "Dashboard",
            "Leave & Absence Tracker",
            "Holiday Calendar",
        ]

        for option in expected_options:
            if not await is_visible_text(option):
                raise AssertionError(
                    f"Side navigation option was not found: {option}"
                )

        print("\nSide navigation validation passed:")

        for option in expected_options:
            print(f"- {option}")

